// === Tab: Car ===
class Car {
	constructor(pos, pvel, rad, ang, dir) {
		this.pos = pos;
		this.pvel = pvel;
		this.rad = rad;
		this.ang = ang;
		this.avel = 0;
		this.dir = dir;
		this.f = color(random(20, 120), random(20, 120), random(20, 120));
		this.alive = true;
		this.signaling = true;
	}
	show() {
		if ((abs(this.pos.y - height / 2) < dim / 2.2) && this.pvel.y != 0) return;
		push();
		translate(this.pos);
		rotate(this.ang);
		translate(0, this.rad);
		fill(255, 70);
		noStroke();
		fill(this.f);
		rect(0, 0, 0.24 * dim, 0.13 * dim, 0.05 * dim);
		if (this.dir == 'east' || this.dir == 'north') {
			fill(0, 150);
			rect(-0.02 * dim, 0, 0.02 * dim, 0.12 * dim, 0.04 * dim);
			fill(255);
			ellipse(-0.10 * dim, -0.04 * dim, 0.04 * dim);
			ellipse(-0.10 * dim, 0.04 * dim, 0.04 * dim);
			fill(255, 0, 0);
			if (this.signaling) ellipse(0.11 * dim, -0.05 * dim, 0.03 * dim + 0.03 * dim * sin(frameCount / 6));
			else ellipse(0.11 * dim, -0.05 * dim, 0.02 * dim);
			ellipse(0.11 * dim, 0.05 * dim, 0.02 * dim);
		} else {
			fill(0, 150);
			rect(0.02 * dim, 0, 0.02 * dim, 0.12 * dim, 0.04 * dim);
			fill(255);
			ellipse(0.10 * dim, -0.04 * dim, 0.04 * dim);
			ellipse(0.10 * dim, 0.04 * dim, 0.04 * dim);
			fill(255, 0, 0);
			ellipse(-0.11 * dim, -0.05 * dim, 0.02 * dim);
			if (this.signaling) ellipse(-0.11 * dim, 0.05 * dim, 0.03 * dim + 0.03 * dim * sin(frameCount / 6));
			else ellipse(-0.11 * dim, 0.05 * dim, 0.02 * dim);
		}
		pop();
	}
	move() {
		this.pos.add(this.pvel);
		this.ang += this.avel;
		if (this.pos.x > ex || this.pos.x < wx || this.pos.y > height + dim || this.pos.y < -dim) this.alive = false;
		switch (this.dir) {
			case 'west':
				if (this.pos.x >= width / 2 + 1.17 * dim) {
					this.pvel.x = 0;
					this.avel = PI / 90;
				}
				if (this.ang > 3 * HALF_PI) {
					this.avel = 0;
					this.pvel.y = -5 * (height / 566);
					this.signaling = false;
					this.pos.x = width / 2 + 1.2 * dim;
				}
				break;
			case 'east':
				if (this.pos.x <= width / 2 - 1.17 * dim) {
					this.pvel.x = 0;
					this.avel = PI / 90;
				}
				if (this.ang > 3 * HALF_PI) {
					this.avel = 0;
					this.pvel.y = 5 * (height / 566);
					this.signaling = false;
					this.pos.x = width / 2 - 1.2 * dim

				}
				break;
			case 'north':
				if (this.pos.y <= height / 2 - 1.175 * dim) {
					this.pvel.y = 0;
					this.avel = PI / 90;
				}
				if (this.ang > TWO_PI) {
					this.avel = 0;
					this.pvel.x = -5 * (height / 566);
					this.signaling = false;
					this.pos.y = height / 2 - 1.2 * dim;
				}
				break;
			case 'south':
				if (this.pos.y >= height / 2 + 1.175 * dim) {
					this.pvel.y = 0;
					this.avel = PI / 90;
				}
				if (this.ang > TWO_PI) {
					this.avel = 0;
					this.pvel.x = 5 * (height / 566);
					this.signaling = false;
					this.pos.y = height / 2 + 1.2 * dim;
				}
				break;
		}
	}
}

// === Tab: mySketch ===
let sky;
let cars = [];
let dim;
let wx, ex;

function setup() {
	createCanvas(windowWidth, windowHeight);
	wx = width / 2 - 1.5 * height;
	ex = width / 2 + 1.5 * height;
	dim = 100 * (height / 566);
	rectMode(CENTER);
	makeCars();
}

function draw() {
	background(0,5);
	drawRoads();
	noStroke();
	cars = cars.filter(c => c.alive);
	for (let c of cars) {
		c.move();
		c.show();
	}
	drawBridge();
	if (frameCount % 60 == 0) makeCars();
}

function makeCars() {
	pos = createVector(wx, height / 2 + 1.2 * dim);
	pvel = createVector(5 * (height / 566), 0);
	cars.push(new Car(pos, pvel, -dim, 0, 'west'));
	pos = createVector(ex, height / 2 - 1.2 * dim);
	pvel = createVector(-5 * (height / 566), 0);
	cars.push(new Car(pos, pvel, dim, 0, 'east'));
	pos = createVector(width / 2 + 1.2 * dim, height + dim);
	pvel = createVector(0, -5 * (height / 566));
	cars.push(new Car(pos, pvel, dim, HALF_PI, 'north'));
	pos = createVector(width / 2 - 1.2 * dim, -dim);
	pvel = createVector(0, 5 * (height / 566));
	cars.push(new Car(pos, pvel, -dim, HALF_PI, 'south'));
}

function drawRoads() {
	stroke(255, 80);
	strokeWeight(2);
	fill(0);
	circle(width / 2 + 1.2 * dim, height / 2 - dim * 1.2, dim * 2.5);
	circle(width / 2 - 1.2 * dim, height / 2 - dim * 1.2, dim * 2.5);
	circle(width / 2 - 1.2 * dim, height / 2 + dim * 1.2, dim * 2.5);
	circle(width / 2 + 1.2 * dim, height / 2 + dim * 1.2, dim * 2.5);
	strokeWeight(dim / 15);
	circle(width / 2 + 1.2 * dim, height / 2 - dim * 1.2, dim * 1.5);
	circle(width / 2 - 1.2 * dim, height / 2 - dim * 1.2, dim * 1.5);
	circle(width / 2 - 1.2 * dim, height / 2 + dim * 1.2, dim * 1.5);
	circle(width / 2 + 1.2 * dim, height / 2 + dim * 1.2, dim * 1.5);
	fill(0);
	stroke(255, 80);
	strokeWeight(2*height/566);
	rect(width / 2, height / 2, 2 * dim / 3, height * 1.5);
	rect(width / 2, height / 2, width * 1.5, 2 * dim / 3);
	stroke(200, 200, 0, 200);
	for (let x = 0; x < width; x += (Math.max(0.001, Math.abs(dim / 4)) || 1)) {
		line(x, height / 2, x + dim / 8, height / 2);
	}
	for (let y = 0; y < height / 2 - dim / 2; y += (Math.max(0.001, Math.abs(dim / 4)) || 1)) {
		line(width / 2, y, width / 2, y + dim / 8);
	}
	for (let y = height / 2 + dim / 2; y < height; y += (Math.max(0.001, Math.abs(dim / 4)) || 1)) {
		line(width / 2, y, width / 2, y + dim / 8);
	}
}

function drawBridge() {
	fill(80);
	rect(width / 2, height / 2 + 10 * dim / 24, 1.75 * dim, dim / 6, 0, 0, dim / 12, dim / 12);
	rect(width / 2, height / 2 - 10 * dim / 24, 1.75 * dim, dim / 6, dim / 12, dim / 12, 0, 0);
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

